int second_largest(int a[],int n)
{int i,m,s;
/*m=a[0];s=a[1];if(m<s){i=m;m=s;s=i;}*/
for(i=0;i<n;i++)
 {
 if(a[i]>m){s=m;m=a[i];}
 else if(a[i]>s){s=a[i];}
 }
return s;
}
